// ============================================================
// 02 - Processar Leads | Code - Deduplicar e Padronizar
// Responsabilidades:
//   - Remover duplicados (por número)
//   - Validar e padronizar telefone brasileiro
//   - Formatar data para Brasília (UTC-3)
//   - Classificar tipo do contato
//   - Preparar estrutura final para o Google Sheets
// ============================================================

const itens = $input.all();

if (!itens || itens.length === 0) {
  return [{ json: { leads: [], total: 0, mensagem: 'Nenhum item recebido' } }];
}

// ── Helpers ──────────────────────────────────────────────────

function normalizarTelefone(numero) {
  // Remove tudo que não for dígito
  let n = numero.toString().replace(/\D/g, '');

  // Se não começar com 55 (DDI Brasil), adiciona
  if (!n.startsWith('55')) {
    n = '55' + n;
  }

  // Formato esperado: 55 + DDD (2) + número (8 ou 9 dígitos)
  // Total: 12 (fixo) ou 13 (celular) dígitos
  if (n.length < 12 || n.length > 13) return null;

  return n;
}

function formatarData(timestamp) {
  if (!timestamp) return '';
  try {
    const d = new Date(timestamp);
    if (isNaN(d.getTime())) return '';
    // Formata para Brasília (UTC-3)
    return d.toLocaleString('pt-BR', {
      timeZone: 'America/Sao_Paulo',
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  } catch (e) {
    return '';
  }
}

function classificarTipo(nome, pushName, numero) {
  // Sem nome salvo na agenda
  if (!nome || nome === numero) {
    return pushName ? 'Sem Nome (tem apelido)' : 'Sem Nome';
  }
  return 'Contato';
}

function dataImportacao() {
  return new Date().toLocaleString('pt-BR', {
    timeZone: 'America/Sao_Paulo',
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit'
  });
}

// ── Processar e deduplicar ────────────────────────────────────

const vistos = new Set();
const leads = [];

for (const item of itens) {
  const d = item.json;

  // Ignorar itens de controle (sem número real)
  if (d.nenhumPost || d.total === 0 || !d.numero) continue;

  // Normalizar telefone
  const numeroNorm = normalizarTelefone(d.numero);
  if (!numeroNorm) continue;

  // Deduplicar por número
  if (vistos.has(numeroNorm)) continue;
  vistos.add(numeroNorm);

  const nome = (d.nome || '').trim();
  const pushName = (d.pushName || '').trim();
  const tipo = classificarTipo(nome, pushName, numeroNorm);

  leads.push({
    json: {
      Nome: nome || pushName || numeroNorm,
      WhatsApp: numeroNorm,
      PushName: pushName,
      UltimaMensagem: (d.ultimaMensagem || '').trim(),
      DataUltimaConversa: formatarData(d.timestamp),
      Tipo: tipo,
      ImportadoEm: dataImportacao()
    }
  });
}

if (leads.length === 0) {
  return [{ json: { leads: [], total: 0, mensagem: 'Nenhum lead válido após processamento' } }];
}

return leads;
